//! The PostgreSQL repository of products against a real database
//! migrated with the application's migrations: round trip, optimistic
//! locking and cursor pages, plus tenant isolation. Generated by
//! `forge generate scaffold`.
//!
//! PostgreSQL tests run as the runtime role an application serves with
//! (`forge::db::testing::RlsTestDatabase`: a fresh migration role applies
//! the migrations, a fresh `NOSUPERUSER NOBYPASSRLS` role with data
//! privileges only runs the queries; both are dropped afterwards), so
//! row-level security applies to them as in production. They need
//! `FORGE_TEST_DATABASE_URL` (a superuser, as in the generated Compose
//! service and CI) and are ignored by default:
//! `cargo test -- --include-ignored`.

use std::error::Error;

use app::application::ports::product_repository::{ProductRepository, ProductStoreError};
use app::application::use_cases::products::WRITE_PERMISSION;
use app::domain::entities::product::{Product, ProductAttributes};
use app::infrastructure::database::products::PgProductRepository;
use forge::auth::{Session, UnixTimestamp};
use forge::core::Version;
use forge::db::PgDatabase;
use forge::db::testing::RlsTestDatabase;
use forge::security::{Permission, PrincipalId, RbacPolicy, Role};
use forge::tenancy::{Membership, TenantContext, TenantId};

type TestResult = Result<(), Box<dyn Error>>;

static MIGRATOR: sqlx::migrate::Migrator = sqlx::migrate!();

fn attributes() -> Result<ProductAttributes, Box<dyn Error>> {
    Ok(ProductAttributes {
        name: "Example name".to_owned(),
        summary: Some("Example summary".to_owned()),
        price_cents: 42,
    })
}

/// An authorized context of `tenant`, built like the HTTP adapter builds it.
fn context(tenant: TenantId) -> Result<TenantContext, Box<dyn Error>> {
    let principal = PrincipalId::new();
    let authenticated = Session::new(
        principal,
        UnixTimestamp::from_secs(10),
        UnixTimestamp::from_secs(20),
    )?
    .authenticate(UnixTimestamp::from_secs(11))?;
    let role = Role::new("member")?;
    let permission = Permission::new(WRITE_PERMISSION)?;
    let mut policy = RbacPolicy::new();
    policy.allow(role.clone(), permission.clone());
    let membership = Membership::active(tenant, principal, vec![role]);
    Ok(TenantContext::authorize(
        authenticated,
        &membership,
        &policy,
        &permission,
    )?)
}

async fn exercise(database: &PgDatabase) -> TestResult {
    let repository = PgProductRepository::new(database.clone());
    let tenant = context(TenantId::new())?;
    let other = context(TenantId::new())?;
    let product = Product::new(attributes()?)?;

    repository.insert(&tenant, &product).await?;
    assert_eq!(
        repository.find(&tenant, product.id()).await?,
        Some(product.clone())
    );

    let version = repository.update(&tenant, &product).await?;
    assert_eq!(version.get(), 2);
    assert!(matches!(
        repository.update(&tenant, &product).await,
        Err(ProductStoreError::Conflict)
    ));
    assert!(matches!(
        repository
            .delete(&tenant, product.id(), Version::INITIAL)
            .await,
        Err(ProductStoreError::Conflict)
    ));
    let stored = repository.find(&tenant, product.id()).await?;
    assert_eq!(stored.map(|stored| stored.version()), Some(version));

    for _ in 0..2 {
        repository
            .insert(&tenant, &Product::new(attributes()?)?)
            .await?;
    }
    let first = repository.page(&tenant, None, 2).await?;
    assert_eq!(first.products.len(), 2);
    assert_eq!(first.products[0].id(), product.id());
    assert!(first.next.is_some());
    let rest = repository.page(&tenant, first.next, 2).await?;
    assert_eq!(rest.products.len(), 1);
    assert!(rest.next.is_none());

    // Another tenant sees nothing and cannot change or delete the row.
    assert_eq!(repository.find(&other, product.id()).await?, None);
    assert!(repository.page(&other, None, 10).await?.products.is_empty());
    let current = product.clone().with_version(version);
    assert!(matches!(
        repository.update(&other, &current).await,
        Err(ProductStoreError::Conflict)
    ));
    assert!(matches!(
        repository.delete(&other, product.id(), version).await,
        Err(ProductStoreError::Conflict)
    ));
    assert!(repository.find(&tenant, product.id()).await?.is_some());

    repository.delete(&tenant, product.id(), version).await?;
    assert_eq!(repository.find(&tenant, product.id()).await?, None);
    Ok(())
}

/// PostgreSQL's `42501`, also raised for a row that violates a row-level
/// security policy.
fn insufficient_privilege<T>(result: &Result<T, sqlx::Error>) -> bool {
    matches!(
        result,
        Err(sqlx::Error::Database(error)) if error.code().as_deref() == Some("42501")
    )
}

#[tokio::test]
#[ignore = "needs FORGE_TEST_DATABASE_URL"]
async fn postgres_round_trip_locking_and_pages() -> TestResult {
    let database = RlsTestDatabase::create([&MIGRATOR]).await?;
    exercise(database.runtime()).await?;
    database.cleanup().await?;
    Ok(())
}

/// The runtime role holds data privileges only: whatever an attacker makes
/// the application run, it cannot create, change, empty or drop a
/// table or switch its row-level security off.
#[tokio::test]
#[ignore = "needs FORGE_TEST_DATABASE_URL"]
async fn postgres_runtime_role_cannot_change_the_schema() -> TestResult {
    let database = RlsTestDatabase::create([&MIGRATOR]).await?;
    for statement in [
        r#"CREATE TABLE "intruders" ("id" uuid)"#,
        r#"CREATE TEMPORARY TABLE "scratch" ("id" uuid)"#,
        r#"ALTER TABLE "products" ADD COLUMN "intruder" text"#,
        r#"ALTER TABLE "products" DISABLE ROW LEVEL SECURITY"#,
        r#"ALTER TABLE "products" NO FORCE ROW LEVEL SECURITY"#,
        r#"DROP POLICY "products_tenant_isolation" ON "products""#,
        r#"TRUNCATE "products""#,
        r#"DROP TABLE "products""#,
    ] {
        let refused = sqlx::query(statement)
            .execute(database.runtime().pool())
            .await;
        assert!(
            insufficient_privilege(&refused),
            "the runtime role ran {statement}: {refused:?}"
        );
    }
    database.cleanup().await?;
    Ok(())
}

/// Row-level security isolates tenants even for SQL that forgets the tenant
/// predicate: as the runtime role the application serves with, a
/// transaction without `forge.tenant_id` sees no row, another tenant's sees
/// none either, the tenant's own sees its row, and no row can move to
/// another tenant.
#[tokio::test]
#[ignore = "needs FORGE_TEST_DATABASE_URL"]
async fn postgres_row_level_security_isolates_tenants() -> TestResult {
    let database = RlsTestDatabase::create([&MIGRATOR]).await?;
    let repository = PgProductRepository::new(database.runtime().clone());
    let tenant = context(TenantId::new())?;
    let other = TenantId::new();
    repository
        .insert(&tenant, &Product::new(attributes()?)?)
        .await?;

    let mut transaction = database.runtime().pool().begin().await?;
    let count = r#"SELECT count(*) FROM "products""#;
    let set_tenant = "SELECT set_config('forge.tenant_id', $1, true)";

    let visible: i64 = sqlx::query_scalar(count)
        .fetch_one(&mut *transaction)
        .await?;
    assert_eq!(visible, 0, "no tenant setting: no row is visible");

    sqlx::query(set_tenant)
        .bind(other.to_string())
        .execute(&mut *transaction)
        .await?;
    let visible: i64 = sqlx::query_scalar(count)
        .fetch_one(&mut *transaction)
        .await?;
    assert_eq!(visible, 0, "another tenant sees no row");

    sqlx::query(set_tenant)
        .bind(tenant.tenant_id().to_string())
        .execute(&mut *transaction)
        .await?;
    let visible: i64 = sqlx::query_scalar(count)
        .fetch_one(&mut *transaction)
        .await?;
    assert_eq!(visible, 1, "the tenant sees its row");

    let moved = sqlx::query(r#"UPDATE "products" SET "tenant_id" = $1"#)
        .bind(other)
        .execute(&mut *transaction)
        .await;
    assert!(
        insufficient_privilege(&moved),
        "a row must not move to another tenant: {moved:?}"
    );

    transaction.rollback().await?;
    database.cleanup().await?;
    Ok(())
}
